define(['local_lid/prompt_editor'],function(PromptEditor){'use strict';function init(){document.querySelectorAll('.lid-forum-config').forEach(function(wrapper){initForumConfig(wrapper);});PromptEditor.init();}
function initForumConfig(wrapper){var forumid=parseInt(wrapper.dataset.forumid,10);var courseid=parseInt(wrapper.dataset.courseid,10);var ajaxUrl=wrapper.dataset.url;var toggle=wrapper.querySelector('.lid-forum-enable-toggle');var statusEl=wrapper.querySelector('.lid-forum-config-status');var promptSection=wrapper.querySelector('.lid-forum-prompt-section');var modelSection=wrapper.querySelector('.lid-forum-model-section');var competencySection=wrapper.querySelector('.lid-forum-competency-section');var modelSaveBtn=wrapper.querySelector('.lid-model-save-btn');var modelStatus=wrapper.querySelector('.lid-model-save-status');if(!toggle||!forumid||!courseid){return;}
updateSectionVisibility(promptSection,toggle.checked);updateSectionVisibility(modelSection,toggle.checked);updateSectionVisibility(competencySection,toggle.checked);updateStatusBadge(statusEl,toggle.checked);toggle.addEventListener('change',function(){var enabling=toggle.checked;if(!enabling){var hasData=wrapper.dataset.hasData==='1';if(hasData){var confirmed=window.confirm('Disabling LID for this forum will stop new analyses from running. '+
'Existing analysis data will not be deleted. Continue?');if(!confirmed){toggle.checked=true;return;}}}
saveForumConfig(forumid,courseid,enabling,getSelectedModel(wrapper),ajaxUrl,toggle,statusEl,function(success){if(success){updateSectionVisibility(promptSection,enabling);updateSectionVisibility(modelSection,enabling);updateSectionVisibility(competencySection,enabling);updateStatusBadge(statusEl,enabling);updateNavTabVisibility(enabling);}else{toggle.checked=!enabling;}});});if(modelSaveBtn){modelSaveBtn.addEventListener('click',function(){var model=getSelectedModel(wrapper);modelSaveBtn.disabled=true;if(modelStatus){modelStatus.textContent='Saving…';modelStatus.style.color='#5a7090';}
saveForumConfig(forumid,courseid,toggle.checked,model,ajaxUrl,toggle,null,function(success){modelSaveBtn.disabled=false;if(success){wrapper.dataset.discussionModel=model;updateModelOptionStyles(wrapper,model);if(modelStatus){modelStatus.textContent='Assessment model saved.';modelStatus.style.color='var(--lid-accent3)';setTimeout(function(){modelStatus.textContent='';},3000);}}else{if(modelStatus){modelStatus.textContent='Save failed.';modelStatus.style.color='#ff3c3c';}}});});}
var radios=wrapper.querySelectorAll('.lid-forum-model-radio');radios.forEach(function(radio){radio.addEventListener('change',function(){updateModelOptionStyles(wrapper,radio.value);});});initCompetencySelector(wrapper,forumid,courseid,ajaxUrl);}
function initCompetencySelector(wrapper,forumid,courseid,ajaxUrl){var modeRadios=wrapper.querySelectorAll('.lid-competency-mode-radio');var checklist=wrapper.querySelector('.lid-competency-checklist');var saveBtn=wrapper.querySelector('.lid-competency-save-btn');var statusEl=wrapper.querySelector('.lid-competency-save-status');if(!modeRadios.length){return;}
modeRadios.forEach(function(radio){radio.addEventListener('change',function(){if(checklist){if(radio.value==='specific'){checklist.classList.remove('lid-forum-prompt-hidden');}else{checklist.classList.add('lid-forum-prompt-hidden');}}});});if(saveBtn){saveBtn.addEventListener('click',function(){var mode=getSelectedCompetencyMode(wrapper);var ids=getSelectedCompetencyIds(wrapper);saveBtn.disabled=true;if(statusEl){statusEl.textContent='Saving…';statusEl.style.color='#5a7090';}
saveForumCompetencies(forumid,courseid,mode,ids,ajaxUrl,function(success){saveBtn.disabled=false;if(success){wrapper.dataset.competencyMode=mode;wrapper.dataset.competencyIds=JSON.stringify(ids);if(statusEl){statusEl.textContent='Competency settings saved.';statusEl.style.color='var(--lid-accent3)';setTimeout(function(){statusEl.textContent='';},3000);}}else{if(statusEl){statusEl.textContent='Save failed.';statusEl.style.color='#ff3c3c';}}});});}}
function getSelectedCompetencyMode(wrapper){var checked=wrapper.querySelector('.lid-competency-mode-radio:checked');return checked?checked.value:'inherit';}
function getSelectedCompetencyIds(wrapper){var ids=[];wrapper.querySelectorAll('.lid-competency-checkbox:checked').forEach(function(cb){ids.push(parseInt(cb.value,10));});return ids;}
function saveForumConfig(forumid,courseid,enabled,discussionModel,ajaxUrl,toggle,statusEl,onDone){toggle.disabled=true;if(statusEl){statusEl.textContent='Saving…';statusEl.style.color='#5a7090';}
var body=new URLSearchParams();body.set('action','forum_config');body.set('forumid',forumid);body.set('courseid',courseid);body.set('enabled',enabled?'1':'0');body.set('discussion_model',discussionModel||'open_engagement');body.set('sesskey',M.cfg.sesskey);fetch(ajaxUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:body.toString(),}).then(function(r){return r.json();}).then(function(data){toggle.disabled=false;if(data.error){showToast(data.message||'Save failed.','error');if(statusEl){statusEl.textContent='Save failed.';statusEl.style.color='#ff3c3c';}
onDone(false);}else{showToast(enabled?'LID analysis enabled for this forum.':'LID analysis disabled for this forum.','success');if(statusEl){statusEl.textContent='';}
onDone(true);}}).catch(function(){toggle.disabled=false;showToast('Save failed. Check your connection.','error');if(statusEl){statusEl.textContent='Save failed.';statusEl.style.color='#ff3c3c';}
onDone(false);});}
function saveForumCompetencies(forumid,courseid,mode,ids,ajaxUrl,onDone){var body=new URLSearchParams();body.set('action','save_forum_competencies');body.set('forumid',forumid);body.set('courseid',courseid);body.set('competency_mode',mode);body.set('competency_ids',JSON.stringify(ids));body.set('sesskey',M.cfg.sesskey);fetch(ajaxUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:body.toString(),}).then(function(r){return r.json();}).then(function(data){if(data.error){showToast(data.message||'Save failed.','error');onDone(false);}else{showToast(data.message||'Competency settings saved.','success');onDone(true);}}).catch(function(){showToast('Save failed. Check your connection.','error');onDone(false);});}
function updateSectionVisibility(section,enabled){if(!section){return;}
if(enabled){section.classList.remove('lid-forum-prompt-hidden');}else{section.classList.add('lid-forum-prompt-hidden');}}
function updateStatusBadge(statusEl,enabled){if(!statusEl){return;}
statusEl.textContent=enabled?'Enabled':'Disabled';statusEl.style.color=enabled?'var(--lid-accent3)':'var(--lid-muted)';statusEl.style.fontSize='10px';statusEl.style.fontFamily="'DM Mono', monospace";}
function updateModelOptionStyles(wrapper,selectedValue){wrapper.querySelectorAll('.lid-forum-model-radio').forEach(function(radio){var label=radio.closest('.lid-model-option');if(!label){return;}
if(radio.value===selectedValue){label.classList.add('lid-model-option-selected');label.style.borderColor='var(--lid-accent)';label.style.background='rgba(0,229,255,0.04)';}else{label.classList.remove('lid-model-option-selected');label.style.borderColor='var(--lid-border)';label.style.background='var(--lid-surface2)';}});}
function getSelectedModel(wrapper){var checked=wrapper.querySelector('.lid-forum-model-radio:checked');return checked?checked.value:'open_engagement';}
function updateNavTabVisibility(enabled){var navItem=document.querySelector('a[data-key="local_lid_forum"]');if(navItem){var li=navItem.closest('li');if(li){li.style.display=enabled?'':'none';}}}
function showToast(message,type){var toast=document.createElement('div');toast.textContent=message;toast.style.cssText=['position:fixed','bottom:24px','right:24px','padding:10px 16px','border-radius:6px','font-size:12px','font-family:\'DM Mono\',monospace','z-index:9999','opacity:0','transition:opacity 0.2s',type==='success'?'background:#0e2a1a;color:#00e5a0;border:1px solid #00e5a0':'background:#2a0e0e;color:#ff3c3c;border:1px solid #ff3c3c',].join(';');document.body.appendChild(toast);requestAnimationFrame(function(){toast.style.opacity='1';});setTimeout(function(){toast.style.opacity='0';setTimeout(function(){if(toast.parentNode){toast.parentNode.removeChild(toast);}},200);},3000);}
return{init:init};});
